{
  "approvalBoundary": "Sealed choices approve directions and authoring methods, not unspecified functions, units, coefficients or actual records. This evidence pack does not manufacture numeric approval or original Basic certification.",
  "decisionIds": [
    "D03",
    "D18",
    "D22",
    "D24",
    "D29",
    "D32",
    "D37"
  ],
  "decisions": [
    {
      "row": "D03",
      "chosenOption": "A",
      "applied": "Separate settlement/occupation payment contract and actual fulfillment ledger. Delivery is not a request or reservation."
    },
    {
      "row": "D18",
      "chosenOption": "A",
      "applied": "Decision-time knowledge, authority and feasibility remain separate from observed later performance. Unknown observation is not failure."
    },
    {
      "row": "D22",
      "chosenOption": "B",
      "applied": "Normalize input units first; formulas, coefficients and resulting consumer values remain proposals until exactly approved."
    },
    {
      "row": "D24",
      "chosenOption": "A",
      "applied": "Personal context-adjusted injury result and aggregate loss refer to one loss ledger; aggregate loss cannot apply the same injury again."
    },
    {
      "row": "D29",
      "chosenOption": "A",
      "applied": "Current/max HP and FP are bodily state; needs, mood and labor effects are separate states linked by cause."
    },
    {
      "row": "D32",
      "chosenOption": "A",
      "applied": "Public Lite damage/DR/injury structure is a reference calculation. Seoul real-time execution and modifiers are separate; no turn, pause, speed control or order queue introduced."
    },
    {
      "row": "D37",
      "chosenOption": "A",
      "applied": "Consumers read approved bodily state without writing it; each cause/effect is settled once, not once per producer domain."
    }
  ],
  "sourceClaims": [
    {
      "source": "task-25-gurps-like-basis-20261008/basis.json",
      "anchors": [
        "L-secondary",
        "L-damage",
        "L-injury"
      ],
      "status": "public-Lite-derived-structure-only",
      "originalBasicRuleVerified": false
    },
    {
      "source": "design-finalization-20261006/D02/contract.json",
      "anchors": [
        "acceptedClauses"
      ],
      "status": "existing-accepted-scope",
      "limit": "Prior proposal parts and obsolete Basic dependency wording are not adopted."
    },
    {
      "source": "task-24/cell-verification/d02-norland-d03-ck3/report.md",
      "status": "historical-source-audit-not-current-readiness",
      "limit": "Conflicting historical hunger/inspiration/faith/pain claims are not Seoul numeric rules."
    }
  ],
  "stateSheet": {
    "bodily": "Separate currentHP/maxHP/currentFP/maxFP and injury records; an injury does not delete identity.",
    "needs": "Food deficiency and water deficiency are independent; food sufficient does not establish hydration.",
    "treatment": "Requested is not performed. Completion requires actual provider, place, resources, consent and applicable method. Interrupted work preserves performed progress and consumed materials.",
    "incapacity": "Injury changes action conditions; do not transform any injury into universal action prohibition. Exact thresholds and recovery guards remain proposals.",
    "mood": "Cause-linked independent record; no automatic HP-to-mood or ration-to-mood coefficient.",
    "evaluation": "Decision-time feasibility evidence and later result remain distinct; read only observed fields.",
    "terminal": "Death is supplied by the owning lifecycle decision, never inferred from an invented HP threshold. Keep permanent identity and consumed/history records."
  },
  "outputs": [
    "cause-linked distinct state references",
    "actual treatment progress",
    "typed E_PROPOSAL/E_UNKNOWN/E_STALE/E_DUPLICATE/E_UNIT errors",
    "reference-only worked arithmetic"
  ],
  "exceptions": [
    "Unknown is not zero",
    "Food is not water",
    "Request is not treatment",
    "HP is not mood",
    "One injury is not two aggregate/person losses",
    "One shortage may have distinct effects, but identical cause/effect cannot settle twice"
  ]
}
